import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiDungeon","description":"","frontmatter":{},"headers":[],"relativePath":"modules/dungeon/index.md","filePath":"modules/dungeon/index.md","lastUpdated":0}`),a={name:`modules/dungeon/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakidungeon" tabindex="-1">EmakiDungeon <a class="header-anchor" href="#emakidungeon" aria-label="Permalink to “EmakiDungeon”">​</a></h1><p>EmakiDungeon 是一款组队副本玩法插件: 你和队友组好队伍, 选好难度, 一起进入一份<strong>专属的副本世界</strong>打通关拿奖励</p><ul><li>每支队伍挑战时都会拿到一份从模板<strong>克隆出来的独立世界</strong>, 不同队伍互不干扰, 打完立即销毁</li><li>副本自带完整的挑战流程: 先选难度与掉落分配模式, 再做准备确认, 等世界准备倒计时结束, 就能进入副本</li><li>次数限制按 日 / 周 / 月 三层管理, 支持可挑战时段, 周几, 月周次与冷却</li><li>局内走分配的奖励先进入<strong>暂存区</strong>, 通关才发放; 中途退出或挑战失败则全部作废, 玩家状态按进入前的快照回滚</li><li>自带队伍系统 (邀请/申请/踢人/队伍频道), 副本内聊天默认与外界隔离, 你随时可以切回全局收听</li><li>内置<strong>地图编辑器</strong>: 你在游戏里圈选区域, 放标记, 填方块, 测试开局, 保存后直接回写模板</li><li>流程由 <code>flow.yml</code> 描述: 房间, 波次, 门禁, 分支选项, 触发区, 计时, 击杀目标等 21 类功能模块</li><li><code>type: random</code> 的副本支持<strong>随机地牢生成</strong>: 从采集的房间 / 走廊结构模板按种子拼装全新布局, 同种子确定性可回放, 藏宝图投影导航</li><li>支持 GraalJS 副本脚本与 CoreLib 动作管道, 你可以按副本生命周期挂自定义逻辑</li></ul><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.0.33</code></td></tr><tr><td>构建产物</td><td><code>EmakiDungeon-1.0.33.jar</code></td></tr><tr><td>API 坐标</td><td><code>emaki.jiuwu.craft:emaki-dungeon-api:1.0.4</code> (只给开发者编译用, 不要放进 <code>plugins/</code>)</td></tr><tr><td>主命令</td><td><code>/edungeon</code> (短别名 <code>/ed</code>)</td></tr><tr><td>必需依赖</td><td>EmakiCoreLib (<code>required: true</code>, <code>join-classpath: true</code>)</td></tr><tr><td>可选依赖</td><td>MythicMobs, WorldGuard, PlaceholderAPI, BetterHUD (不装也能用, 只是对应联动停用)</td></tr><tr><td>权限节点</td><td><code>emakidungeon.play</code>, <code>emakidungeon.dungeon.*</code>, <code>emakidungeon.bypass.limit</code>, <code>emakidungeon.bypass.escape</code>, <code>emakidungeon.script</code>, <code>emakidungeon.editor</code>, <code>emakidungeon.admin</code>, <code>emakidungeon.*</code></td></tr><tr><td>支持的平台</td><td>Paper 26.1+, 支持 Folia (<code>folia-supported: true</code>)</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>每个副本还有一个按名字动态注册的权限 <code>emakidungeon.dungeon.&lt;副本ID&gt;</code>, 默认<strong>所有玩家可进入</strong>; 如果你想把某个副本设为特权内容, 把它的默认值改成只有指定权限组持有即可</p></div><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>玩家命令, 队伍子命令, 编辑器会话命令, 管理命令与权限表</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td>全局 <code>config.yml</code>, 副本级 <code>config.yml</code>, 奖励箱界面三份配置的全部键</td></tr><tr><td><a href="./challenges.html">挑战与奖励</a></td><td>进入流程, 次数限制, 队伍规则, 奖励暂存与发放, 失败回滚</td></tr><tr><td><a href="./flow.html">流程与触发器</a></td><td><code>flow.yml</code> 的 21 类功能模块, 编辑器用法, 生命周期动作与脚本</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td>给开发者: <code>emaki-dungeon-api</code> 门面与全部事件</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>实例世界池</td><td>每个副本按&quot;克隆模板&quot;准备世界, 池中默认常驻 2 个备用世界 (<code>pool.warm-reserves</code> 默认 2), 上限可配 (<code>pool.max-worlds</code>, 全局 <code>limit.max-instances</code>); 世界随打随建, 打完卸载删除, 插件重启会自检清理残留</td></tr><tr><td>挑战流程</td><td>队长发起 → 难度选择 → 掉落分配模式选择 → 全员准备确认 (超时作废) → 世界准备等待 (bossbar 或聊天条, 可取消) → 进入并计入次数</td></tr><tr><td>随机地牢生成</td><td><code>type: random</code> 副本按 <code>random-dungeon.yml</code> 从结构模板随机拼装布局, <code>random create</code> 按房量公式出图, 同种子确定性回放校验</td></tr><tr><td>三层次数限制</td><td>每日 / 每周 / 每月各配次数与可挑战窗口, 判定顺序 月 &gt; 周 &gt; 日, 另有独立冷却; 计数按服务器时区或 <code>general.timezone</code> 分桶</td></tr><tr><td>奖励暂存与发放</td><td>局内产出先暂存, 通关时按掉落分配模式结算进奖励箱或背包; 未通关全部作废, 玩家状态按进入前快照还原</td></tr><tr><td>队伍与聊天隔离</td><td>队伍人数与邀请模式可配; 副本内消息默认实例内闭环, <code>/edungeon globalchat on</code> 可切回全服互通, 队伍频道独立</td></tr><tr><td>命令管控</td><td>副本内命令按黑名单/白名单模式过滤, 逃逸类命令 (如 <code>/tp *</code>) 单独黑名单且不可被放行豁免; 越界自动拉回出生点</td></tr><tr><td>地图编辑器</td><td>独立编辑世界, 支持两点圈选, 21 种标记, 区域填充, 面板改字段, 测试开局 (不计次数, 不上榜), 保存才回写模板; <code>type: random</code> 副本另有区域采集 GUI</td></tr><tr><td>评分与排行</td><td>伤害/击杀/治疗/死亡/防御五项贡献权重加时间维度算分, 副本排行榜与个人战绩查询</td></tr><tr><td>生命周期动作</td><td>11 个生命周期段 (<code>dungeon_enter</code> 到 <code>dungeon_destroy</code>) 走 CoreLib 动作管道, 可挂全服广播, 音效等自定义逻辑</td></tr><tr><td>运行监控</td><td>MSPT P95, 堆内存斜率, 写队列积压三项阈值告警 (阈值 <code>&lt;= 0</code> 关闭), 告警进控制台与审计日志</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiDungeon/</span></span>
<span class="line"><span>├── config.yml               ← 主配置 (全局开关与限流)</span></span>
<span class="line"><span>├── random-dungeon.yml       ← 随机地牢生成配置 (type: random 用)</span></span>
<span class="line"><span>├── world/</span></span>
<span class="line"><span>│   └── &lt;副本ID&gt;/</span></span>
<span class="line"><span>│       ├── config.yml       ← 副本配置 (缺失时按模板自动生成)</span></span>
<span class="line"><span>│       ├── flow.yml         ← 流程定义 (缺失时按模板自动生成)</span></span>
<span class="line"><span>│       ├── structures/      ← 随机地牢结构模板 (区域采集落库, type: random 用)</span></span>
<span class="line"><span>│       ├── region/          ← 副本地图的区块存档</span></span>
<span class="line"><span>│       └── entities/        ← 副本地图的实体存档</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   └── rewardbox.yml        ← 奖励箱界面 (页数与容量)</span></span>
<span class="line"><span>├── scripts/                 ← 副本 GraalJS 脚本, 文件名 = &lt;副本ID&gt;.js (可选)</span></span>
<span class="line"><span>├── instances.yml            ← 运行时实例记录 (自动生成, 不要手改)</span></span>
<span class="line"><span>├── random-dungeon/instances/ ← 随机地牢实例记录 (自动生成, 不要手改)</span></span>
<span class="line"><span>├── parties.yml              ← 队伍快照 (自动生成, 不要手改)</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p>副本模板就是 <code>world/</code> 下的一个文件夹, 文件夹名就是副本 ID. 插件在启动和执行 <code>/edungeon admin reload</code> 时扫描该目录, 缺 <code>config.yml</code> 或 <code>flow.yml</code> 会自动按内置模板补上, 已有的不会被覆盖</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to “典型工作流”">​</a></h2><ol><li>先在 <code>plugins/EmakiDungeon/world/</code> 下新建一个文件夹当作副本 ID (例如 <code>my_dungeon</code>), 把你的地图区块放进其中 (或先建空目录, 用编辑器搭)</li><li>重启服务器或执行 <code>/edungeon admin reload</code>, 缺失的 <code>config.yml</code> 与 <code>flow.yml</code> 会自动生成</li><li>执行 <code>/edungeon editor my_dungeon</code> 打开编辑器, 圈区域, 放标记, 搭流程; 改完点&quot;保存并回写模板&quot;</li><li>再手工调 <code>config.yml</code> 里的难度, 次数限制与掉落分配, 调完再次执行 <code>/edungeon admin reload</code></li><li>玩家用 <code>/edungeon list</code> 看有哪些副本, 用 <code>/edungeon enter my_dungeon</code> 发起挑战; 队长选难度, 全员准备后进入</li><li>打完开箱领奖 (<code>/edungeon rewards</code>), 或在配置里关掉奖励箱让产出直接进背包</li></ol><p>想做随机地牢: 把副本 <code>config.yml</code> 的 <code>type</code> 改成 <code>random</code>, 用编辑器的&quot;创建区域&quot; (房间 / 走廊) 采集结构模板, 在 <code>random-dungeon.yml</code> 的 <code>room-types</code> 登记生成权重, 然后 <code>/edungeon random create &lt;副本ID&gt; [人数] [种子]</code> 生成进入</p><h2 id="与其他模块的关系" tabindex="-1">与其他模块的关系 <a class="header-anchor" href="#与其他模块的关系" aria-label="Permalink to “与其他模块的关系”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>协作方式</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td>必需依赖: 调度, 消息, 配置检查与动作管道; 副本生命周期动作由 CoreLib 的动作段执行</td></tr><tr><td>EmakiMobs</td><td>流程刷怪点的生物条目可用 <code>source: emaki-mobs</code> 引用 EmakiMobs 生物定义 (不装则只能用原版实体)</td></tr><tr><td>EmakiItem / EmakiLevel</td><td>副本结算命令 <code>settlement.commands</code> 里可以直接调它们的命令发物品与经验</td></tr><tr><td>MythicMobs / WorldGuard</td><td>可选依赖, 未安装时插件正常运行, 对应联动停用</td></tr></tbody></table><h2 id="placeholderapi-占位符" tabindex="-1">PlaceholderAPI 占位符 <a class="header-anchor" href="#placeholderapi-占位符" aria-label="Permalink to “PlaceholderAPI 占位符”">​</a></h2><p>扩展标识符: <code>emakidungeon</code></p><p>前置条件: PlaceholderAPI 已安装; 满足后 EmakiDungeon 自动注册以下占位符</p><table tabindex="0"><thead><tr><th>占位符</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>%emakidungeon_data_&lt;副本ID&gt;_cleared%</code></td><td>是否已通关该副本</td><td><code>true</code></td></tr><tr><td><code>%emakidungeon_data_&lt;副本ID&gt;_first_clear%</code></td><td>首次通关时间 (Unix 毫秒时间戳, 未通关为 <code>0</code>)</td><td><code>1700000000000</code></td></tr><tr><td><code>%emakidungeon_data_&lt;副本ID&gt;_best_time%</code></td><td>最佳通关用时 (毫秒)</td><td><code>245000</code></td></tr><tr><td><code>%emakidungeon_data_&lt;副本ID&gt;_clear_count%</code></td><td>通关次数</td><td><code>3</code></td></tr><tr><td><code>%emakidungeon_data_&lt;副本ID&gt;_best_score%</code></td><td>最佳评分 (保留 1 位小数)</td><td><code>92.5</code></td></tr><tr><td><code>%emakidungeon_data_&lt;副本ID&gt;_difficulty_&lt;难度&gt;_cleared%</code></td><td>是否通关过指定难度</td><td><code>true</code></td></tr><tr><td><code>%emakidungeon_party_in_party%</code></td><td>是否在队伍中</td><td><code>true</code></td></tr><tr><td><code>%emakidungeon_party_size%</code></td><td>当前队伍人数</td><td><code>4</code></td></tr><tr><td><code>%emakidungeon_party_&lt;来源&gt;_{&lt;PAPI 占位符&gt;}%</code></td><td>以队友为对象解析任意 PlaceholderAPI 占位符</td><td><code>%emakidungeon_party_leader_{player_name}%</code></td></tr></tbody></table><p><code>&lt;来源&gt;</code> 取 <code>self</code> (自己), <code>leader</code> (队长) 或 <code>member_&lt;n&gt;</code> (第 n 名队员, 从 1 开始); 花括号里写不带 <code>%</code> 的 PlaceholderAPI 占位符</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};